// Heavily optimized kernel using vector loads
// Each thread handles one pooled element (16 floats = 4 float4)
// 512 pooled elements per batch = 512 threads per batch
__global__ void fused_avgpool_gelu_scale_max_vec_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int out_features,
    float scale_factor,
    float inv_pool_size  // 1/16 = 0.0625
) {
    // 512 threads per block, one block per batch element
    int batch_idx = blockIdx.x;
    int pool_idx = threadIdx.x;  // 0-511

    if (batch_idx >= batch_size) return;

    // Load and compute average for this pooled element
    // pool_kernel_size = 16, so we read 4 float4s
    const float4* row4 = (const float4*)(input + batch_idx * out_features);
    int start4 = pool_idx * 4;  // Each pooled element = 16 floats = 4 float4s

    float sum = 0.0f;

    float4 v0 = row4[start4];
    float4 v1 = row4[start4 + 1];
    float4 v2 = row4[start4 + 2];
    float4 v3 = row4[start4 + 3];

    sum = v0.x + v0.y + v0.z + v0.w +
          v1.x + v1.y + v1.z + v1.w +
          v2.x + v2.y + v2.z + v2.w +
          v3.x + v3.y + v3.z + v3.w;

    float avg = sum * inv_pool_size;
    float gelu_val = gelu_approx(avg);
    float scaled = gelu_val * scale_factor;

    // Now reduce across the 512 threads
    __shared__ float sdata[512];
    sdata[pool_idx] = scaled;
    __syncthreads();

    // Tree reduction
    for (int s = 256; s > 0; s >>= 1) {
        if (pool_idx < s) {
            sdata[pool_idx] = fmaxf(sdata[pool_idx], sdata[pool_idx + s]);
        }
        __syncthreads();
    }

    if (pool_idx == 0) {
        output[batch_idx] = sdata[0];
    }
